import pytest
from typing import Sequence
from pylint.graph import get_cycles


class TestGetCycles:
    """Test cases for the get_cycles function."""

    def test_empty_graph(self) -> None:
        """Test empty graph dictionary."""
        graph: dict[str, set[str]] = {}
        result = get_cycles(graph)
        assert result == []

    def test_single_vertex_no_edges(self) -> None:
        """Test graph with single vertex and no edges."""
        graph = {"A": set()}
        result = get_cycles(graph)
        assert result == []

    def test_single_vertex_self_loop(self) -> None:
        """Test graph with single vertex having self-loop."""
        graph = {"A": {"A"}}
        result = get_cycles(graph)
        assert len(result) == 1
        assert result[0] == ["A"]

    def test_two_vertices_no_cycles(self) -> None:
        """Test graph with two vertices and no cycles."""
        graph = {"A": {"B"}, "B": set()}
        result = get_cycles(graph)
        assert result == []

    def test_two_vertices_with_cycle(self) -> None:
        """Test graph with two vertices forming a cycle."""
        graph = {"A": {"B"}, "B": {"A"}}
        result = get_cycles(graph)
        assert len(result) == 1
        cycle = result[0]
        assert len(cycle) == 2
        assert set(cycle) == {"A", "B"}

    def test_multiple_vertices_complex_cycles(self) -> None:
        """Test graph with multiple vertices and complex cycles."""
        graph = {
            "A": {"B", "C"},
            "B": {"C"},
            "C": {"D", "E"},
            "D": {"A"},
            "E": {"F"},
            "F": {"E"},
        }
        result = get_cycles(graph)
        assert len(result) == 2
        cycles_set = {tuple(sorted(cycle)) for cycle in result}
        expected_cycles = {("A", "B", "C", "D"), ("E", "F")}
        assert cycles_set == expected_cycles

    def test_disconnected_components_with_cycles(self) -> None:
        """Test graph with disconnected components containing cycles."""
        graph = {
            "A": {"B"},
            "B": {"A"},
            "C": {"D"},
            "D": {"C"},
            "E": set(),
        }
        result = get_cycles(graph)
        assert len(result) == 2
        cycles_set = {tuple(sorted(cycle)) for cycle in result}
        expected_cycles = {("A", "B"), ("C", "D")}
        assert cycles_set == expected_cycles

    def test_specified_vertices_subset_no_cycles(self) -> None:
        """Test with specified vertices that have no cycles."""
        graph = {
            "A": {"B"},
            "B": {"C"},
            "C": {"D"},
            "D": set(),
            "E": {"F"},
            "F": {"E"},
        }
        vertices = ["A", "B", "C", "D"]
        result = get_cycles(graph, vertices)
        assert result == []

    def test_specified_vertices_subset_with_cycles(self) -> None:
        """Test with specified vertices that contain cycles."""
        graph = {
            "A": {"B"},
            "B": {"C"},
            "C": {"A"},
            "D": {"E"},
            "E": {"F"},
            "F": {"D"},
        }
        vertices = ["D", "E", "F"]
        result = get_cycles(graph, vertices)
        assert len(result) == 1
        cycle = result[0]
        assert len(cycle) == 3
        assert set(cycle) == {"D", "E", "F"}

    def test_vertices_none_uses_all_vertices(self) -> None:
        """Test that when vertices is None, all vertices are used."""
        graph = {
            "A": {"B"},
            "B": {"A"},
            "C": {"D"},
            "D": {"C"},
        }
        result1 = get_cycles(graph, None)
        result2 = get_cycles(graph)
        assert result1 == result2
        assert len(result1) == 2

    def test_graph_unchanged_after_call(self) -> None:
        """Test that the original graph dictionary remains unchanged."""
        graph = {"A": {"B"}, "B": {"A"}}
        original_graph = {k: set(v) for k, v in graph.items()}
        _ = get_cycles(graph)
        assert graph == original_graph

    def test_duplicate_vertices_in_input_list(self) -> None:
        """Test with duplicate vertices in the vertices list."""
        graph = {"A": {"B"}, "B": {"C"}, "C": {"A"}}
        vertices = ["A", "B", "A", "C"]
        result = get_cycles(graph, vertices)
        assert len(result) == 1
        assert len(result[0]) == 3

    def test_vertices_not_in_graph(self) -> None:
        """Test with vertices that are not in the graph."""
        graph = {"A": {"B"}, "B": {"C"}}
        vertices = ["A", "D"]
        result = get_cycles(graph, vertices)
        assert result == []

    def test_large_cycle(self) -> None:
        """Test with a large cycle of vertices."""
        graph = {chr(65 + i): {chr(65 + ((i + 1) % 10))} for i in range(10)}
        result = get_cycles(graph)
        assert len(result) == 1
        assert len(result[0]) == 10

    def test_multiple_cycles_with_shared_vertices(self) -> None:
        """Test graph where cycles share vertices."""
        graph = {
            "A": {"B"},
            "B": {"C", "A"},
            "C": {"A"},
        }
        result = get_cycles(graph)
        assert len(result) == 2
        cycles_set = {tuple(sorted(cycle)) for cycle in result}
        expected_cycles = {("A", "B"), ("A", "B", "C")}
        assert cycles_set == expected_cycles

    def test_return_type_sequence(self) -> None:
        """Test that the return type is a Sequence."""
        graph = {"A": {"B"}, "B": {"A"}}
        result = get_cycles(graph)
        assert isinstance(result, Sequence)

